      en: ["Built: 18th century", "City: Niš", "Type: Citadel", "Area: approx. 22 hectares"],
      es: ["Año: Siglo XVIII", "Ciudad: Niš", "Tipo: Ciudadela", "Área: aprox. 22 hectáreas"],
